    distance[s] = 0
    dq = deque([s])

    while dq:
        u = dq.popleft()
        for v, w in adj[u]:
            if distance[v] > distance[u] + w:
                distance[v] = distance[u] + w
                if w == 1:
                    dq.append(v)
                else:
                    dq.appendleft(v)

    return distance[t] if distance[t] != float('inf') else -1
