from collections import deque

def solve(n, edges, s, t):
    if s == t:
        return 0
    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # BFS with priority (0-weight edges first) to find shortest path
    # We'll use a deque for 0-weight edges and a regular queue for others
    # We also track the distance to each node
    dist = [float('inf')] * n
    dist[s] = 0
    zero_queue = deque()
    non_zero_queue = deque()

    for v, w in adj[s]:
        if w == 0:
            zero_queue.append((v, w))
        else:
            non_zero_queue.append((v, w))

    # Process nodes in order of 0-weight edges first
    while zero_queue or non_zero_queue:
        if zero_queue:
            v, w = zero_queue.popleft()
        else:
            v, w = non_zero_queue.popleft()

        if dist[v] != float('inf'):
            continue

        if dist[s] + w < dist[v]:
            dist[v] = dist[s] + w
            for neighbor, weight in adj[v]:
                if weight == 0:
                    zero_queue.append((neighbor, weight))
                else:
                    non_zero_queue.append((neighbor, weight))

    return dist[t] if dist[t] != float('inf') else -1
